import React from 'react';
import './Stats.css';

const Stats = ({ todos }) => {
  const total = todos.length;
  const completed = todos.filter(t => t.status === 'completed').length;
  const inProgress = todos.filter(t => t.status === 'in_progress').length;
  const yetToStart = todos.filter(t => t.status === 'yet_to_start').length;
  const recurring = todos.filter(t => t.isRecurring).length;

  const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

  return (
    <div className="stats">
      <h3>📊 Statistics</h3>

      <div className="stat-item">
        <div className="stat-label">Total Tasks</div>
        <div className="stat-value">{total}</div>
      </div>

      <div className="stat-item">
        <div className="stat-label">Yet to Start</div>
        <div className="stat-value yet-to-start">{yetToStart} ⭕</div>
      </div>

      <div className="stat-item">
        <div className="stat-label">In Progress</div>
        <div className="stat-value in-progress">{inProgress} ⏳</div>
      </div>

      <div className="stat-item">
        <div className="stat-label">Completed</div>
        <div className="stat-value completed">{completed} ✅</div>
      </div>

      <div className="stat-item">
        <div className="stat-label">Recurring</div>
        <div className="stat-value recurring">{recurring} 🔄</div>
      </div>

      <div className="progress-bar">
        <div className="progress-label">Completion Rate</div>
        <div className="progress-track">
          <div
            className="progress-fill"
            style={{ width: `${completionRate}%` }}
          ></div>
        </div>
        <div className="progress-value">{completionRate}%</div>
      </div>
    </div>
  );
};

export default Stats;
